package orchestrator.core

import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.security.SecureRandom
import java.util.Base64
import scala.util.matching.Regex
import scala.collection.concurrent.TrieMap

object EncryptedStorage {
  private val GCM_TAG_LENGTH = 128
  private val GCM_IV_LENGTH = 12
  private val keyStore = new TrieMap[String, Array[Byte]]()

  def generateKey(): Array[Byte] = {
    val key = new Array[Byte](32)
    new SecureRandom().nextBytes(key)
    key
  }

  def encrypt(data: Array[Byte], key: Array[Byte]): String = {
    val iv = new Array[Byte](GCM_IV_LENGTH)
    new SecureRandom().nextBytes(iv)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(key, "AES"), new GCMParameterSpec(GCM_TAG_LENGTH, iv))
    val encrypted = cipher.doFinal(data)
    Base64.getEncoder.encodeToString(iv ++ encrypted)
  }

  def decrypt(encoded: String, key: Array[Byte]): Array[Byte] = {
    val decoded = Base64.getDecoder.decode(encoded)
    val iv = decoded.take(GCM_IV_LENGTH)
    val ciphertext = decoded.drop(GCM_IV_LENGTH)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(key, "AES"), new GCMParameterSpec(GCM_TAG_LENGTH, iv))
    cipher.doFinal(ciphertext)
  }

  def storeSecret(namespace: String, name: String, data: Array[Byte]): Unit = {
    val key = generateKey()
    val encrypted = encrypt(data, key)
    keyStore.put(s"$namespace/$name", key)
    SecretRegistry.register(namespace, name, encrypted)
  }
}

object ContainerSpec {
  // Validates container resource specification format
  // Format: <namespace>/<service>:<version>@<digest>
  // Allows nested group references like service.sub.component
  private val specPattern: Regex =
    """^([a-z][a-z0-9-]*)/([a-z](?:[a-z0-9]*\.)*[a-z0-9]+):([a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)?@(sha256:[a-f0-9]{64})$""".r

  def validate(spec: String): Boolean = {
    specPattern.findFirstMatchIn(spec).isDefined
  }

  def parse(spec: String): Option[ContainerReference] = {
    specPattern.findFirstMatchIn(spec).map { m =>
      ContainerReference(
        namespace = m.group(1),
        service = m.group(2),
        version = m.group(3),
        digest = m.group(4)
      )
    }
  }
}

case class ContainerReference(
  namespace: String,
  service: String,
  version: String,
  digest: String
)

object SecretRegistry {
  private val registry = new TrieMap[String, String]()

  def register(namespace: String, name: String, encryptedData: String): Unit = {
    registry.put(s"$namespace/$name", encryptedData)
  }

  def lookup(namespace: String, name: String): Option[String] = {
    registry.get(s"$namespace/$name")
  }
}

object DeploymentValidator {
  // Validates deployment manifest label selectors
  // Labels follow k8s conventions: prefix/name with specific char rules
  // The prefix is optional and can be a DNS subdomain
  private val labelKeyPattern: Regex =
    """^(([a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?\.)*[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?/)?[a-zA-Z0-9]([a-zA-Z0-9._-]*[a-zA-Z0-9])?$""".r

  private val labelValuePattern: Regex =
    """^([a-zA-Z0-9]([a-zA-Z0-9._-]*[a-zA-Z0-9])?)?$""".r

  def validateLabel(key: String, value: String): Boolean = {
    if (key.length > 253 + 1 + 63) return false
    if (value.length > 63) return false
    labelKeyPattern.findFirstMatchIn(key).isDefined &&
      labelValuePattern.findFirstMatchIn(value).isDefined
  }

  def validateDeployment(labels: Map[String, String], spec: String): Either[String, ContainerReference] = {
    val labelsValid = labels.forall { case (k, v) => validateLabel(k, v) }
    if (!labelsValid) return Left("Invalid label format")

    ContainerSpec.parse(spec) match {
      case Some(ref) => Right(ref)
      case None => Left("Invalid container spec format")
    }
  }
}

object Orchestrator {
  def deploy(namespace: String, service: String, version: String,
             digest: String, labels: Map[String, String],
             secretData: Option[Array[Byte]]): Either[String, String] = {
    val spec = s"$namespace/$service:$version@$digest"

    DeploymentValidator.validateDeployment(labels, spec) match {
      case Left(err) => Left(err)
      case Right(ref) =>
        secretData.foreach { data =>
          EncryptedStorage.storeSecret(ref.namespace, ref.service, data)
        }
        Right(s"Deployed ${ref.service} v${ref.version} in ${ref.namespace}")
    }
  }
}
